def localized(language: str, key: str, **values):
    value = UI_TEXT[language][key]
    return value.format(**values) if isinstance(value, str) and values else value

EMBED_RED_DOT_B64 = """"""

def _load_embedded_red_map(size_wh):
    data = base64.b64decode(EMBED_RED_DOT_B64.encode("ascii"))
    im = Image.open(io.BytesIO(data)).convert("RGBA")
    if im.size != size_wh:
        im = im.resize(size_wh, Image.NEAREST)
    return im

def pil_to_qimage(im: Image.Image) -> QtGui.QImage:
    if im.mode != "RGBA": im = im.convert("RGBA")
    data = im.tobytes("raw", "RGBA")
    # Detach from the temporary Python bytes object before returning.
    return QtGui.QImage(data, im.width, im.height, QtGui.QImage.Format_RGBA8888).copy()

def qimage_to_qpixmap(qimg: QtGui.QImage) -> QtGui.QPixmap:
    return QtGui.QPixmap.fromImage(qimg)

def apply_opacity(img: Image.Image, alpha_val: int) -> Image.Image:
    alpha_val = max(0, min(255, int(alpha_val)))
    if img.mode != "RGBA": img = img.convert("RGBA")
    r,g,b,a = img.split()
    if alpha_val < 255: a = a.point(lambda t: (t * alpha_val) // 255)
    return Image.merge("RGBA", (r,g,b,a))

def make_checkerboard(size, tile=16, c1=(200,200,200), c2=(150,150,150)) -> Image.Image:
    w,h = size; img = Image.new("RGB", (w,h), c1); d = ImageDraw.Draw(img)
    for y in range(0,h,tile):
        for x in range(0,w,tile):
            if ((x//tile)+(y//tile))%2==0:
                d.rectangle([x,y,x+tile-1,y+tile-1], fill=c2)
    return img

def resize_cover(img: Image.Image, size):
    w,h = size
    if img.mode != "RGBA": img = img.convert("RGBA")
    iw,ih = img.size
    if iw==0 or ih==0 or w==0 or h==0:
        return Image.new("RGBA", size, (0,0,0,255))
    scale = max(w/iw, h/ih); nw,nh = int(iw*scale), int(ih*scale)
    img = img.resize((nw,nh), Image.LANCZOS)
    left = max(0,(nw-w)//2); top = max(0,(nh-h)//2)
    return img.crop((left, top, left+w, top+h))

class GlyphSet:
    def __init__(self, folders):
        if isinstance(folders, (str, bytes, os.PathLike)): folders = [folders]
        self.folders = [f for f in folders if f]; self.cache = {}
    def get(self, ch: str) -> Image.Image:
        key = (ch or "").upper()
        if key in self.cache: return self.cache[key]
        if key.isspace():
            img = Image.new("RGBA", (10, 28), (0, 0, 0, 0))
            self.cache[key] = img
            return img
        if key.isalnum():
            name = f"{key}.png"
            for folder in self.folders:
                path = os.path.join(folder, name)
                if os.path.exists(path):
                    try:
                        with Image.open(path) as source:
                            img = source.convert("RGBA")
                    except Exception: img = self._placeholder()
                    self.cache[key] = img; return img
        img = self._placeholder(); self.cache[key] = img; return img
    def _placeholder(self) -> Image.Image:
        w,h = 20,28; img = Image.new("RGBA",(w,h),(0,0,0,0)); d = ImageDraw.Draw(img)
        d.rectangle([1,1,w-2,h-2], outline=(0,0,0,255)); d.line((1,1,w-2,h-2), fill=(0,0,0,255)); d.line((w-2,1,1,h-2), fill=(0,0,0,255))
        return img

def rasterize_char_with_font(ch: str, font_path: str, size: int) -> Image.Image:
    try: font = ImageFont.truetype(font_path, size=size)
    except Exception: font = ImageFont.load_default()
    if ch==" ":
        w = max(1, int(size*0.33)); h = max(1, int(size*1.0))
        return Image.new("RGBA", (w,h), (0,0,0,0))
    try: bbox = font.getbbox(ch)
    except Exception: bbox=None
    if bbox:
        x0,y0,x1,y1 = bbox; w=max(1,x1-x0+4); h=max(1,y1-y0+4)
        mask = Image.new("L",(w,h),0); d = ImageDraw.Draw(mask); d.text((2-x0,2-y0), ch, font=font, fill=255)
    else:
        w=max(10,int(size*2)); h=max(10,int(size*2))
        mask = Image.new("L",(w,h),0); d = ImageDraw.Draw(mask); d.text((2,2), ch, font=font, fill=255)
        bb2 = mask.getbbox()
        if bb2: x0,y0,x1,y1 = bb2; mask = mask.crop((x0,y0,x1,y1))
    rgba = Image.new("RGBA", mask.size, (0,0,0,0)); rgba.putalpha(mask); return rgba

def add_noise_to_glyph(glyph: Image.Image, density: float=0.03, colorful: float=0.0) -> Image.Image:
    g = glyph.copy(); px = g.load(); w,h = g.size
    for y in range(h):
        for x in range(w):
            _,_,_,a = px[x,y]
            if a>0 and random.random()<density:
                if random.random()<colorful:
                    rr=random.randint(0,255); gg2=random.randint(0,255); bb=random.randint(0,255); px[x,y]=(rr,gg2,bb,a)
                else:
                    val = random.choice([0,255]); px[x,y]=(val,val,val,a)
    return g

def feather_glyph_edges(glyph: Image.Image, feather: int=0) -> Image.Image:
    if feather<=0: return glyph
    if glyph.mode!="RGBA": glyph=glyph.convert("RGBA")
    r,g,b,a = glyph.split(); a=a.filter(ImageFilter.GaussianBlur(max(1,int(feather)))); return Image.merge("RGBA",(r,g,b,a))

def make_colored_glow(glyph: Image.Image, spread:int=6, feather:int=8, alpha:int=120,
                      color_mix:float=0.0, noise_density:float=0.0, noise_colorful:float=0.0) -> Tuple[Image.Image,int]:
    if glyph.mode!="RGBA": glyph=glyph.convert("RGBA")
    pad = max(2, int(spread + 2*feather + 2)); a_small = glyph.split()[-1]
    big_size = (glyph.width + pad*2, glyph.height + pad*2)
    a = Image.new("L", big_size, 0); a.paste(a_small, (pad,pad))
    if spread and spread>0:
        size = int(spread)*2+1
        try: a = a.filter(ImageFilter.MaxFilter(size))
        except Exception: a = a.filter(ImageFilter.BoxBlur(max(1,int(spread))))
    if feather and feather>0: a=a.filter(ImageFilter.GaussianBlur(max(1,int(feather))))
    hue = random.random()
    def hsv_to_rgb(h,s,v):
        i = int(h*6); f=h*6-i; p=int(255*v*(1-s)); q=int(255*v*(1-f*s)); t=int(255*v*(1-(1-f)*s)); v=int(255*v); i%=6
        return [(v,t,p),(q,v,p),(p,v,t),(p,q,v),(t,p,v),(v,p,q)][i]
    base_color = hsv_to_rgb(hue,0.8,1.0)
    glow = Image.new("RGBA", a.size, base_color + (0,)); glow.putalpha(a.point(lambda x: min(255,int(x*(alpha/255.0)))))
    if color_mix and color_mix>0.0:
        mix=max(0.0,min(1.0,float(color_mix))); px=glow.load(); w,h=glow.size
        for yy in range(h):
            for xx in range(w):
                r,g,b,aa = px[xx,yy]
                if aa>0:
                    tr=random.randint(0,255); tg=random.randint(0,255); tb=random.randint(0,255)
                    nr=int(r*(1.0-mix)+tr*mix); ng=int(g*(1.0-mix)+tg*mix); nb=int(b*(1.0-mix)+tb*mix)
                    px[xx,yy]=(nr,ng,nb,aa)
    if noise_density and noise_density>0.0:
        px=glow.load(); w,h=glow.size
        for yy in range(h):
            for xx in range(w):
                r,g,b,aa = px[xx,yy]
                if aa>0 and random.random()<noise_density:
                    if random.random()<noise_colorful:
                        rr=random.randint(0,255); gg2=random.randint(0,255); bb2=random.randint(0,255); px[xx,yy]=(rr,gg2,bb2,aa)
                    else:
                        jitter=random.randint(-40,40)
                        rr=max(0,min(255,r+jitter)); gg2=max(0,min(255,g+jitter)); bb2=max(0,min(255,b+jitter))
                        px[xx,yy]=(rr,gg2,bb2,aa)
    return glow, pad

def stamp_code_onto(base: Image.Image, code: str, at_xy: Tuple[int,int], glyphs_png: Optional[GlyphSet],
                    scale: float=1.0, spacing:int=1, jitter_all:int=2, jitter_char:int=1, noise_density: float=0.03,
                    noise_colorful: float=0.0, glow_spread:int=6, glow_feather:int=8, glow_alpha:int=120,
                    glow_color_mix:float=0.0, glow_noise_density:float=0.0, glow_noise_colorful:float=0.0,
                    glyph_alpha:int=255, offset_x:int=0, offset_y:int=0, edge_feather:int=0,
                    use_sys_font: bool=False, font_path: Optional[str]=None, font_size:int=48) -> None:
    code = code or ""
    if not code:
        return
    per_char_images: List[Image.Image] = []; unique_cache: Dict[str, Image.Image] = {}
    if use_sys_font and font_path:
        for ch in code:
            key = f"F|{ch}|{font_path}|{font_size}"
            if key not in unique_cache: unique_cache[key] = rasterize_char_with_font(ch, font_path, font_size)
            per_char_images.append(unique_cache[key])
    else:
        for ch in code:
            g0 = glyphs_png.get(ch.upper()) if glyphs_png else Image.new("RGBA",(20,28),(0,0,0,0))
            per_char_images.append(g0)
    scaled_sizes: List[Tuple[int,int]] = []; max_h=0; total_w=0
    for g0 in per_char_images:
        gw=max(1,int(round(g0.width*scale))); gh=max(1,int(round(g0.height*scale)))
        scaled_sizes.append((gw,gh)); total_w+=gw; max_h=max(max_h,gh)
    if len(per_char_images)>1: total_w += spacing*(len(per_char_images)-1)
    cur_x = int(round(at_xy[0] - total_w/2.0)) + int(offset_x)
    cur_y = int(round(at_xy[1] - max_h/2.0)) - int(offset_y)  # 正值向上
    cur_x += random.randint(-jitter_all, jitter_all); cur_y += random.randint(-jitter_all, jitter_all)
    for idx,g0 in enumerate(per_char_images):
        gw,gh = scaled_sizes[idx]; g=g0
        if (g.width,g.height)!=(gw,gh): g = g.resize((gw,gh), Image.LANCZOS if use_sys_font else Image.NEAREST)
        g = feather_glyph_edges(g, feather=int(edge_feather)); g = add_noise_to_glyph(g, density=noise_density, colorful=noise_colorful)
        g_for_glow = g; g = apply_opacity(g, glyph_alpha)
        spread_eff=max(0,int(round(glow_spread*max(0.5,scale)))); feather_eff=max(0,int(round(glow_feather*max(0.5,scale))))
        glow,pad = make_colored_glow(g_for_glow, spread=spread_eff, feather=feather_eff, alpha=glow_alpha,
                                     color_mix=glow_color_mix, noise_density=glow_noise_density, noise_colorful=glow_noise_colorful)
        ox = cur_x + random.randint(-jitter_char, jitter_char); oy = cur_y + random.randint(-jitter_char, jitter_char)
        base.alpha_composite(glow, (ox-pad, oy-pad)); base.alpha_composite(g, (ox, oy))
        # Character jitter is relative to the common baseline; it must not
        # accumulate into a random walk across a long code string.
        cur_x += g.width + spacing

def _render_chunk(size_wh, points, code, glyph_dirs, params) -> bytes:
    w,h = size_wh; layer = Image.new("RGBA",(w,h),(0,0,0,0))
    glyphs = GlyphSet(glyph_dirs) if not params.get("use_sys_font", False) else None
    for (x,y) in points:
        stamp_code_onto(layer, code, (x,y), glyphs,
                        scale=params["scale"], spacing=params["spacing"],
                        jitter_all=params["jitter_all"], jitter_char=params["jitter_char"],
                        noise_density=params["noise_density"], noise_colorful=params["noise_colorful"],
                        glow_spread=params["glow_spread"], glow_feather=params["glow_feather"],
                        glow_alpha=params["glow_alpha"], glow_color_mix=params["glow_color_mix"],
                        glow_noise_density=params["glow_noise_density"], glow_noise_colorful=params["glow_noise_colorful"],
                        glyph_alpha=params["glyph_alpha"], offset_x=params["offset_x"], offset_y=params["offset_y"],
                        edge_feather=params["edge_feather"], use_sys_font=params.get("use_sys_font", False),
                        font_path=params.get("font_path"), font_size=params.get("font_size", 48))
    buf = io.BytesIO(); layer.save(buf, format="PNG"); return buf.getvalue()

def extract_red_points(red_map: Image.Image, merge_components: bool) -> List[Tuple[int,int]]:
    # threshold
    px = red_map.load(); w,h = red_map.size
    if not merge_components:
        pts = []
        for y in range(h):
            for x in range(w):
                r,g,b,a = px[x,y]
                if a>0 and r>=200 and g<=60 and b<=60:
                    pts.append((x,y))
        return pts
    # Connected components (4-neighborhood)
    visited = bytearray(w*h)
    pts_out: List[Tuple[int,int]] = []
    for y0 in range(h):
        row_off = y0*w
        for x0 in range(w):
            idx0 = row_off + x0
            if visited[idx0]: continue
            r,g,b,a = px[x0,y0]
            if not (a>0 and r>=200 and g<=60 and b<=60): 
                continue
            # BFS
            q = collections.deque()
            q.append((x0,y0)); visited[idx0]=1
            sumx=sumy=count=0
            minx=miny=10**9; maxx=maxy=-1
            while q:
                x,y = q.popleft()
                sumx += x; sumy += y; count += 1
                if x<minx: minx=x
                if y<miny: miny=y
                if x>maxx: maxx=x
                if y>maxy: maxy=y
                for nx,ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0<=nx<w and 0<=ny<h:
                        i2 = ny*w + nx
                        if visited[i2]: continue
                        rr,gg,bb,aa = px[nx,ny]
                        if aa>0 and rr>=200 and gg<=60 and bb<=60:
                            visited[i2]=1; q.append((nx,ny))
            # choose centroid or bbox center (integer)
            if count>0:
                cx = int(round(sumx / count))
                cy = int(round(sumy / count))
                pts_out.append((cx, cy))
    return pts_out

class RenderWorkerMP(QtCore.QThread):
    progress = QtCore.Signal(int, int, str); finished_img = QtCore.Signal(object); error = QtCore.Signal(str)
    def __init__(self, base_image: Image.Image, points: List[Tuple[int,int]], code: str,
                 glyph_dirs: List[str], params: dict, workers: int, chunk_size: int, language: str="zh"):
        super().__init__(); self.base_image = base_image.copy(); self.points=list(points); self.code=code
        self.glyph_dirs=glyph_dirs; self.params=params; self.workers=max(1,int(workers)); self.chunk_size=max(1,int(chunk_size)); self.language=language
    def _compose_parallel(self, executor, chunks, total, mode_label):
        """Render with bounded in-flight jobs and composite in source order."""
        out = self.base_image.copy(); size_wh = self.base_image.size; processed = 0
        chunk_iter = iter(chunks); pending = collections.deque()
        max_in_flight = max(1, self.workers * 2)

        def submit_next():
            try:
                idx, pts = next(chunk_iter)
            except StopIteration:
                return False
            future = executor.submit(_render_chunk, size_wh, pts, self.code, self.glyph_dirs, self.params)
            pending.append((idx, len(pts), future))
            return True

        for _ in range(min(max_in_flight, len(chunks))):
            submit_next()
        while pending:
            idx, pts_len, future = pending.popleft()
            png_bytes = future.result()
            with Image.open(io.BytesIO(png_bytes)) as source:
                layer = source.convert("RGBA")
            out.alpha_composite(layer)
            processed += pts_len
            self.progress.emit(processed, total, localized(self.language, "progress", batch=idx+1,
                               batches=len(chunks), processed=processed, total=total, mode=mode_label))
            submit_next()
        return out

    def run(self):
        try:
            total=len(self.points)
            if total==0: self.error.emit(localized(self.language, "no_points")); return
            chunks=[(i//self.chunk_size, self.points[i:i+self.chunk_size]) for i in range(0,total,self.chunk_size)]
            self.progress.emit(0,total,localized(self.language, "parallel_start", batches=len(chunks)))
            try:
                from concurrent.futures import ProcessPoolExecutor
                import multiprocessing as mp
                ctx = mp.get_context("spawn")
                with ProcessPoolExecutor(max_workers=self.workers, mp_context=ctx) as ex:
                    out = self._compose_parallel(ex, chunks, total, localized(self.language, "proc_mode"))
            except Exception as e1:
                self.progress.emit(0,total,localized(self.language, "proc_fallback"))
                try:
                    from concurrent.futures import ThreadPoolExecutor
                    with ThreadPoolExecutor(max_workers=self.workers) as ex:
                        out = self._compose_parallel(ex, chunks, total, localized(self.language, "thread_mode"))
                except Exception as e2:
                    self.progress.emit(0,total,localized(self.language, "single_fallback"))
                    out = self.base_image.copy(); processed = 0
                    for idx,pts in chunks:
                        png_bytes=_render_chunk(self.base_image.size, pts, self.code, self.glyph_dirs, self.params)
                        with Image.open(io.BytesIO(png_bytes)) as source:
                            layer = source.convert("RGBA")
                        out.alpha_composite(layer); processed+=len(pts)
                        self.progress.emit(processed,total,localized(self.language, "progress", batch=idx+1,
                                           batches=len(chunks), processed=processed, total=total,
                                           mode=localized(self.language, "single_mode")))
            self.finished_img.emit(out)
        except Exception as e: self.error.emit(str(e))

class ImageView(QtWidgets.QGraphicsView):
    doubleClicked = QtCore.Signal()
    resized = QtCore.Signal()
    zoomChanged = QtCore.Signal(int)
    MIN_ZOOM = 0.01
    MAX_ZOOM = 8.0
    ZOOM_STEP = 1.2
    ZOOM_FRAME_MS = 16
    def __init__(self, parent=None):
        super().__init__(parent)
        self.setRenderHint(QtGui.QPainter.Antialiasing, False)
        self.setRenderHint(QtGui.QPainter.SmoothPixmapTransform, False)
        self.setViewportUpdateMode(QtWidgets.QGraphicsView.MinimalViewportUpdate)
        self.setOptimizationFlags(
            QtWidgets.QGraphicsView.DontSavePainterState |
            QtWidgets.QGraphicsView.DontAdjustForAntialiasing
        )
        self.setHorizontalScrollBarPolicy(QtCore.Qt.ScrollBarAlwaysOff)
        self.setVerticalScrollBarPolicy(QtCore.Qt.ScrollBarAlwaysOff)
        self.setDragMode(QtWidgets.QGraphicsView.ScrollHandDrag); self.setTransformationAnchor(QtWidgets.QGraphicsView.AnchorUnderMouse)
        self._default_transform = QtGui.QTransform(); self.setBackgroundBrush(QtGui.QBrush(QtGui.QColor("#222")))
        self._zoom_target = 1.0
        self._zoom_timer = QtCore.QTimer(self)
        self._zoom_timer.setSingleShot(True)
        self._zoom_timer.setInterval(self.ZOOM_FRAME_MS)
        self._zoom_timer.timeout.connect(self._apply_pending_zoom)
        self.empty_label = QtWidgets.QLabel(self.viewport())
        self.empty_label.setAttribute(QtCore.Qt.WA_TransparentForMouseEvents, True)
        self.empty_label.setAlignment(QtCore.Qt.AlignCenter)
        empty_font = self.empty_label.font()
        empty_font.setPointSize(22); empty_font.setBold(True)
        self.empty_label.setFont(empty_font)
        self.empty_label.setStyleSheet("background: transparent; color: #ffffff; border: none; padding: 0; font-size: 22pt; font-weight: bold;")
        self.empty_label.hide()
    def setEmptyMessage(self, text: str, visible: bool, dark_text=None):
        self.empty_label.setText(text)
        if dark_text is not None:
            color = "#000000" if dark_text else "#ffffff"
            self.empty_label.setStyleSheet(
                f"background: transparent; color: {color}; border: none; padding: 0; font-size: 22pt; font-weight: bold;"
            )
        self.empty_label.adjustSize()
        self.empty_label.setVisible(visible)
        if visible:
            self.empty_label.raise_()
        self._position_empty_label()
    def _position_empty_label(self):
        x = max(0, (self.viewport().width() - self.empty_label.width()) // 2)
        y = max(0, (self.viewport().height() - self.empty_label.height()) // 2)
        self.empty_label.move(x, y)
    def resizeEvent(self, event: QtGui.QResizeEvent):
        super().resizeEvent(event)
        self._position_empty_label()
        self.resized.emit()
    def _current_zoom(self):
        base_scale = max(0.000001, abs(self._default_transform.m11()))
        return max(0.000001, abs(self.transform().m11()) / base_scale)
    def _apply_pending_zoom(self):
        current_zoom = self._current_zoom()
        factor = self._zoom_target / current_zoom
        if not math.isclose(factor, 1.0, rel_tol=0.0, abs_tol=1e-9):
            self.scale(factor, factor)
        self._zoom_target = self._current_zoom()
        self.zoomChanged.emit(int(round(self._zoom_target * 100)))
    def _queue_zoom_steps(self, steps):
        if math.isclose(steps, 0.0, rel_tol=0.0, abs_tol=1e-12):
            return
        base_zoom = self._zoom_target if self._zoom_timer.isActive() else self._current_zoom()
        target_zoom = base_zoom * (self.ZOOM_STEP ** steps)
        self._zoom_target = max(self.MIN_ZOOM, min(self.MAX_ZOOM, target_zoom))
        if not self._zoom_timer.isActive() and not math.isclose(
                self._zoom_target, self._current_zoom(), rel_tol=0.0, abs_tol=1e-9):
            self._zoom_timer.start()
    def zoomIn(self):
        self._queue_zoom_steps(1.0)
    def zoomOut(self):
        self._queue_zoom_steps(-1.0)
    def wheelEvent(self, event: QtGui.QWheelEvent):
        delta = event.angleDelta().y()
        if delta == 0:
            event.ignore()
            return
        self._queue_zoom_steps(delta / 120.0)
        event.accept()
    def resetZoom(self):
        self._zoom_timer.stop()
        self.setTransform(self._default_transform)
        self._zoom_target = 1.0
        self.zoomChanged.emit(100)
    def mouseDoubleClickEvent(self, event: QtGui.QMouseEvent):
        self.resetZoom(); self.doubleClicked.emit(); super().mouseDoubleClickEvent(event)

class HoverInfoButton(QtWidgets.QPushButton):
    NORMAL_STYLE = """
        QPushButton { background:#343434; color:#eeeeee; border:1px solid #5c5c5c;
        border-radius:4px; padding:0; font-weight:bold; }"""
    HOVER_STYLE = """
        QPushButton { background:#356f91; color:#eeeeee; border:1px solid #72d1ff;
        border-radius:4px; padding:0; font-weight:bold; }"""
    PRESSED_STYLE = """
        QPushButton { background:#17445f; color:#eeeeee; border:1px solid #72d1ff;
        border-radius:4px; padding:0; font-weight:bold; }"""

    def __init__(self, title: str, msg: str, parent=None):
        super().__init__("?", parent)
        self._title = title
        self.tip = msg
        self.tipBox = None
        self.setFixedSize(28, 28)
        self.setFocusPolicy(QtCore.Qt.NoFocus)
        self.setCursor(QtCore.Qt.PointingHandCursor)
        self.setStyleSheet(self.NORMAL_STYLE)

    def showTip(self):
        if self.tipBox:
            self.tipBox.close()
        self.tipBox = QtWidgets.QLabel(self.tip, None, QtCore.Qt.ToolTip)
        self.tipBox.setStyleSheet("""
            background: #222; color:#fff; border-radius:8px; border:1.5px solid #999;
            font-size:14px; padding:10px 18px; min-width:210px; max-width:350px;""")
        self.tipBox.setWordWrap(True)
        pos = self.mapToGlobal(self.rect().bottomRight())
        screen = QtGui.QGuiApplication.screenAt(pos)
        if not screen:
            screen = QtWidgets.QApplication.primaryScreen()
        scr_geo = screen.geometry()
        self.tipBox.adjustSize()
        w, h = self.tipBox.width(), self.tipBox.height()
        x = min(pos.x() + 12, scr_geo.right() - w - 16)
        y = min(pos.y() - 12, scr_geo.bottom() - h - 16)
        x = max(scr_geo.left() + 8, x)
        y = max(scr_geo.top() + 8, y)
        self.tipBox.move(x, y)
        self.tipBox.show()

    def enterEvent(self, event: QtCore.QEvent):
        self.setStyleSheet(self.HOVER_STYLE)
        self.showTip()
        super().enterEvent(event)

    def leaveEvent(self, event: QtCore.QEvent):
        self.setStyleSheet(self.NORMAL_STYLE)
        self.hideTip()
        super().leaveEvent(event)

    def mousePressEvent(self, event: QtGui.QMouseEvent):
        if event.button() != QtCore.Qt.LeftButton:
            super().mousePressEvent(event)
            return
        self.setStyleSheet(self.PRESSED_STYLE)
        if self.tipBox and self.tipBox.isVisible():
            self.hideTip()
        else:
            self.showTip()
        event.accept()

    def mouseReleaseEvent(self, event: QtGui.QMouseEvent):
        if event.button() == QtCore.Qt.LeftButton:
            self.setStyleSheet(self.HOVER_STYLE if self.rect().contains(event.position().toPoint()) else self.NORMAL_STYLE)
            event.accept()
            return
        super().mouseReleaseEvent(event)

    def hideTip(self):
        if self.tipBox:
            self.tipBox.close()
            self.tipBox = None

class HoverTipCheckBox(QtWidgets.QCheckBox):
    """Show the same custom popup as ? help, but only over the label text."""
    def __init__(self, text: str, tip: str, parent=None):
        super().__init__(text, parent)
        self.tip = tip
        self.tipBox = None
        self._text_hovered = False
        self.setMouseTracking(True)
        super().setToolTip("")

    def setToolTip(self, text: str):
        self.tip = text
        super().setToolTip("")
        if self.tipBox is not None:
            self.tipBox.setText(text)
            self.tipBox.adjustSize()

    def _text_rect(self):
        option = QtWidgets.QStyleOptionButton()
        self.initStyleOption(option)
        contents = self.style().subElementRect(
            QtWidgets.QStyle.SE_CheckBoxContents, option, self
        )
        metrics = self.fontMetrics()
        width = metrics.horizontalAdvance(self.text())
        height = metrics.height()
        return QtCore.QRect(
            contents.left(),
            contents.center().y() - height // 2,
            min(width, contents.width()),
            height,
        )

    def _update_text_hover(self, pos: QtCore.QPoint):
        hovered = self._text_rect().contains(pos)
        if hovered == self._text_hovered:
            return
        self._text_hovered = hovered
        self.setCursor(QtCore.Qt.PointingHandCursor if hovered else QtCore.Qt.ArrowCursor)
        if hovered:
            self.showTip()
        else:
            self.hideTip()

    def showTip(self):
        if not self.tip:
            return
        if self.tipBox:
            self.tipBox.close()
        self.tipBox = QtWidgets.QLabel(self.tip, None, QtCore.Qt.ToolTip)
        self.tipBox.setStyleSheet("""
            background: #222; color:#fff; border-radius:8px; border:1.5px solid #999;
            font-size:14px; padding:10px 18px; min-width:210px; max-width:350px;""")
        self.tipBox.setWordWrap(True)
        pos = self.mapToGlobal(self._text_rect().bottomRight())
        screen = QtGui.QGuiApplication.screenAt(pos)
        if not screen:
            screen = QtWidgets.QApplication.primaryScreen()
        screen_rect = screen.geometry()
        self.tipBox.adjustSize()
        x = min(pos.x() + 12, screen_rect.right() - self.tipBox.width() - 16)
        y = min(pos.y() - 12, screen_rect.bottom() - self.tipBox.height() - 16)
        self.tipBox.move(max(screen_rect.left() + 8, x), max(screen_rect.top() + 8, y))
        self.tipBox.show()

    def hideTip(self):
        if self.tipBox:
            self.tipBox.close()
            self.tipBox = None

    def enterEvent(self, event: QtCore.QEvent):
        self._update_text_hover(self.mapFromGlobal(QtGui.QCursor.pos()))
        super().enterEvent(event)

    def mouseMoveEvent(self, event: QtGui.QMouseEvent):
        self._update_text_hover(event.position().toPoint())
        super().mouseMoveEvent(event)

    def leaveEvent(self, event: QtCore.QEvent):
        self._text_hovered = False
        self.setCursor(QtCore.Qt.ArrowCursor)
        self.hideTip()
        super().leaveEvent(event)

class ButtonInteractionFilter(QtCore.QObject):
    """Match Fragmenter Pro v1.3.1 button hover/press feedback."""
    def eventFilter(self, obj, event):
        if isinstance(obj, QtWidgets.QPushButton):
            event_type = event.type()
            if event_type == QtCore.QEvent.Enter and obj.isEnabled():
                self._set_button_state(obj, "hover")
            elif event_type == QtCore.QEvent.MouseButtonPress and obj.isEnabled():
                self._set_button_state(obj, "pressed")
            elif event_type == QtCore.QEvent.MouseButtonRelease and obj.isEnabled():
                self._set_button_state(obj, "hover" if obj.underMouse() else "normal")
            elif event_type in (QtCore.QEvent.Leave, QtCore.QEvent.EnabledChange):
                self._set_button_state(obj, "normal")
        return False

    @staticmethod
    def _set_button_state(button, state):
        current_effect = button.graphicsEffect()
        own_effect = getattr(button, "_interaction_effect", None)
        if own_effect is None and current_effect is not None:
            button._interaction_original_effect = current_effect
        if state == "normal" or not button.isEnabled():
            if current_effect is own_effect:
                button.setGraphicsEffect(getattr(button, "_interaction_original_effect", None))
            button._interaction_effect = None
            return
        effect = QtWidgets.QGraphicsColorizeEffect(button)
        if state == "pressed":
            effect.setColor(QtGui.QColor("#12384d")); effect.setStrength(0.62)
        else:
            effect.setColor(QtGui.QColor("#72d1ff")); effect.setStrength(0.32)
        button._interaction_effect = effect
        button.setGraphicsEffect(effect)

class MainWindow(QtWidgets.QMainWindow):
    def __init__(self):
        super().__init__()
        self._button_interaction_filter = ButtonInteractionFilter(self)
        app = QtWidgets.QApplication.instance()
        if app is not None:
            app.installEventFilter(self._button_interaction_filter)
        self.language = "zh"
        self._form_i18n = []
        self.setWindowTitle(UI_TEXT[self.language]["title"])
        # The parameter panel needs about 993 px at this font size. Keeping the
        # window at 1000 px prevents the 24 px help buttons and rows from being
        # vertically compressed.
        self.setMinimumSize(1280,1000)
        self.resize(1380,1000)
        # Match the visual system used by MSW Skin Fragmenter Pro v1.3.1.
        self.setStyleSheet("""
            QWidget {
                background: #232323;
                color: #eeeeee;
                font-size: 15px;
            }
            QMenu {
                background: #2b2b2b;
                color: #eeeeee;
                border: 1px solid #5a5a5a;
                padding: 4px;
            }
            QMenu::item {
                background: transparent;
                padding: 6px 30px 6px 12px;
                border-radius: 3px;
            }
            QMenu::item:selected:enabled {
                background: #287fbd;
                color: #ffffff;
            }
            QMenu::item:disabled {
                color: #777777;
            }
            QMenu::separator {
                height: 1px;
                background: #555555;
                margin: 4px 8px;
            }
            QToolTip {
                background: #222222;
                color: #ffffff;
                border: 1px solid #999999;
                padding: 6px 10px;
            }
        """)
